if (size <= 0) return nullptr;

auto cmp = [](const std::pair<TreeNode*, double>& a, const std::pair<TreeNode*, double>& b) {
    return a.second > b.second;
};
std::priority_queue<std::pair<TreeNode*, double>,
                    std::vector<std::pair<TreeNode*, double>>,
                    decltype(cmp)> pq(cmp);

for (int i = 0; i < size; ++i) {
    TreeNode* leaf = new TreeNode(values[i], freqs[i]);
    pq.emplace(leaf, freqs[i]);
}

while (pq.size() > 1) {
    auto left = pq.top(); pq.pop();
    auto right = pq.top(); pq.pop();

    double combinedFreq = left.second + right.second;
    TreeNode* internal = new TreeNode(-1, combinedFreq);
    internal->left = left.first;
    internal->right = right.first;

    pq.emplace(internal, combinedFreq);
}

return pq.empty() ? nullptr : pq.top().first;
// END_CODE

